// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 wrongGuess, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(wrongGuess != bytes32(0));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(wrongGuess);

        vm.roll(block.number + 2);

        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        vm.assume(wrongGuess != answer);

        uint256 balBefore = address(actor).balance;

        vm.prank(actor);
        c.settle();

        assertTrue(address(actor).balance == balBefore, "settle paid 2 ether to a guesser whose guess did not match the answer");
    }
}
